// Check if point is on any polygon edge (boundary)
for (std::size_t i = 0; i < polygon.size(); ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[(i + 1) % polygon.size()];

    if (CGAL::collinear(p1, p2, point) &&
        CGAL::between(p1, p2, point)) {
        return ON_BOUNDARY;
    }
}

// Ray casting algorithm
int intersection_count = 0;
for (std::size_t i = 0; i < polygon.size(); ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[(i + 1) % polygon.size()];

    // Check if point is a vertex
    if (p1 == point || p2 == point) {
        return ON_BOUNDARY;
    }

    // Check if ray intersects with edge
    if (CGAL::do_intersect(
        p1, p2,
        point,
        Point_2(p1.x() + 1, p1.y()))) {  // Ray direction (right)

        // Check if intersection is proper (not at vertex)
        if (CGAL::collinear(p1, p2, point)) {
            continue;
        }

        // Check if intersection is with a horizontal edge
        if (p1.y() == p2.y() && point.y() == p1.y()) {
            if (point.x() >= std::min(p1.x(), p2.x()) &&
                point.x() <= std::max(p1.x(), p2.x())) {
                return ON_BOUNDARY;
            }
        }

        intersection_count++;
    }
}

// Determine result based on intersection count
if (intersection_count % 2 == 1) {
    return ON_BOUNDED_SIDE;
} else {
    return ON_UNBOUNDED_SIDE;
}

